import type { LocalAiState } from '@motivation/shared';

/**
 * Story 426: the one line both the AI section and the home widget show for the switch. A timed
 * hold past its `until` reads as off: the server released it then.
 */
export function localAiLabel(state: LocalAiState, now: Temporal.Instant): string {
    if (state.mode === 'kept') return 'Kept on';
    if (state.mode === 'off' || state.until === null) return 'Off';
    const ms = Temporal.Instant.from(state.until).epochMilliseconds - now.epochMilliseconds;
    if (ms <= 0) return 'Off';
    return `On · ${Math.ceil(ms / 60_000)} min left`;
}
